style.css:
@-moz-document domain("youtube.com") {
/* =========================================
     TEMA HOT ROD (TRANSFORMERS G1) - YOUTUBE
     ========================================= */

  :root {
    --hr-red-dark: #2a0408;
    --hr-red-main: #8b0015;
    --hr-red-bright: #d90429;
    --hr-orange: #ff5400;
    --hr-yellow: #ffbd00;
    --hr-gray-metal: #1c1c21;
    --hr-text-light: #fff8f0;
  }

  /* Fondo principal de YouTube (Modo Oscuro recomendado) */
  html[dark], ytd-app, #content.ytd-app, ytd-watch-flexy {
    background-color: #160406 !important;
    color: var(--hr-text-light) !important;
  }

  /* Barra superior de navegación (Header) */
  #masthead-container.ytd-app, ytd-masthead {
    background: linear-gradient(90deg, #59000d 0%, #b8001f 50%, #ff5400 100%) !important;
    border-bottom: 2px solid var(--hr-yellow) !important;
  }

  /* Barra de búsqueda */
  #search-form #container.ytd-searchbox,
  yt-searchbox .ytSearchboxComponentInputBox {
    background-color: #26070a !important;
    border: 1.5px solid var(--hr-yellow) !important;
    color: #ffffff !important;
  }

  #search-icon-legacy.ytd-searchbox,
  yt-searchbox .ytSearchboxComponentSearchButton {
    background-color: var(--hr-yellow) !important;
    border: 1.5px solid var(--hr-yellow) !important;
    color: #1a0000 !important;
  }

  /* Menú lateral izquierdo */
  #guide-content.ytd-app, ytd-mini-guide-renderer, tp-yt-app-drawer #contentContainer {
    background-color: #1f0508 !important;
    border-right: 1px solid #6e0010 !important;
  }

  /* Íconos y textos del menú lateral */
  ytd-guide-entry-renderer[active] {
    background-color: var(--hr-red-bright) !important;
    border-left: 4px solid var(--hr-yellow) !important;
  }

  ytd-guide-entry-renderer:hover {
    background-color: rgba(255, 84, 0, 0.25) !important;
  }

  /* Barra de progreso del reproductor (Llamas de Hot Rod) */
  .ytp-play-progress, .ytp-swatch-background-color {
    background: linear-gradient(90deg, var(--hr-red-bright), var(--hr-orange), var(--hr-yellow)) !important;
  }

  .ytp-scrubber-button {
    background-color: var(--hr-yellow) !important;
    box-shadow: 0 0 10px var(--hr-orange) !important;
  }

  /* Botón de Suscribirse y botones principales */
  ytd-subscribe-button-renderer button,
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled {
    background: linear-gradient(135deg, var(--hr-yellow) 0%, var(--hr-orange) 100%) !important;
    color: #1a0000 !important;
    font-weight: bold !important;
    border: 1px solid #fff !important;
  }

  ytd-subscribe-button-renderer button:hover,
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled:hover {
    background: var(--hr-red-bright) !important;
    color: var(--hr-yellow) !important;
  }

  /* Chips / Etiquetas de categorías arriba del inicio */
  yt-chip-cloud-chip-renderer[selected] #chip-container {
    background-color: var(--hr-yellow) !important;
    color: #1a0000 !important;
    font-weight: bold !important;
  }

  yt-chip-cloud-chip-renderer #chip-container {
    background-color: #38080e !important;
    color: var(--hr-text-light) !important;
    border: 1px solid #8b0015 !important;
  }

  /* Títulos de videos y enlaces */
  #video-title.ytd-rich-grid-media, #video-title.ytd-video-renderer, h1.ytd-watch-metadata {
    color: #ffe8d6 !important;
  }

  #video-title:hover {
    color: var(--hr-yellow) !important;
  }

  /* Borde brillante estilo visor azul/dorado al pasar el mouse por las miniaturas */
  ytd-rich-item-renderer:hover ytd-thumbnail,
  ytd-compact-video-renderer:hover ytd-thumbnail {
    outline: 2px solid var(--hr-yellow) !important;
    box-shadow: 0 0 12px rgba(255, 189, 0, 0.5) !important;
    border-radius: 12px !important;
  }

  /* Barra de desplazamiento (Scrollbar) */
  ::-webkit-scrollbar {
    width: 10px !important;
  }
  ::-webkit-scrollbar-track {
    background: #1a0305 !important;
  }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, var(--hr-red-bright), var(--hr-yellow)) !important;
    border-radius: 5px !important;
  }
}
